// Package litewire provides compact protobuf wire helpers backed by encoding/protowire
// for code generated by cmd/protoc-gen-go-lite.
package litewire

import (
	"math"
	"slices"

	"google.golang.org/protobuf/encoding/protowire"
)

func AppendString(b []byte, num protowire.Number, v string) []byte {
	if v == "" {
		return b
	}
	return AppendStringAlways(b, num, v)
}

func AppendStringAlways(b []byte, num protowire.Number, v string) []byte {
	b = protowire.AppendTag(b, num, protowire.BytesType)
	return protowire.AppendString(b, v)
}

func AppendBytes(b []byte, num protowire.Number, v []byte) []byte {
	if len(v) == 0 {
		return b
	}
	return AppendBytesAlways(b, num, v)
}

func AppendBytesAlways(b []byte, num protowire.Number, v []byte) []byte {
	b = protowire.AppendTag(b, num, protowire.BytesType)
	return protowire.AppendBytes(b, v)
}

func AppendBool(b []byte, num protowire.Number, v bool) []byte {
	if !v {
		return b
	}
	return AppendBoolAlways(b, num, v)
}

func AppendBoolAlways(b []byte, num protowire.Number, v bool) []byte {
	b = protowire.AppendTag(b, num, protowire.VarintType)
	return protowire.AppendVarint(b, protowire.EncodeBool(v))
}

func AppendVarint(b []byte, num protowire.Number, v uint64) []byte {
	if v == 0 {
		return b
	}
	return AppendVarintAlways(b, num, v)
}

func AppendVarintAlways(b []byte, num protowire.Number, v uint64) []byte {
	b = protowire.AppendTag(b, num, protowire.VarintType)
	return protowire.AppendVarint(b, v)
}

func AppendInt32(b []byte, num protowire.Number, v int32) []byte {
	if v == 0 {
		return b
	}
	return AppendVarintAlways(b, num, uint64(int64(v)))
}

func AppendInt32Always(b []byte, num protowire.Number, v int32) []byte {
	return AppendVarintAlways(b, num, uint64(int64(v)))
}

func AppendZigZag(b []byte, num protowire.Number, v int64) []byte {
	if v == 0 {
		return b
	}
	return AppendVarintAlways(b, num, protowire.EncodeZigZag(v))
}

func AppendZigZagAlways(b []byte, num protowire.Number, v int64) []byte {
	return AppendVarintAlways(b, num, protowire.EncodeZigZag(v))
}

func AppendFixed32(b []byte, num protowire.Number, v uint32) []byte {
	if v == 0 {
		return b
	}
	return AppendFixed32Always(b, num, v)
}

func AppendFixed32Always(b []byte, num protowire.Number, v uint32) []byte {
	b = protowire.AppendTag(b, num, protowire.Fixed32Type)
	return protowire.AppendFixed32(b, v)
}

func AppendFixed64(b []byte, num protowire.Number, v uint64) []byte {
	if v == 0 {
		return b
	}
	return AppendFixed64Always(b, num, v)
}

func AppendFixed64Always(b []byte, num protowire.Number, v uint64) []byte {
	b = protowire.AppendTag(b, num, protowire.Fixed64Type)
	return protowire.AppendFixed64(b, v)
}

func AppendFloat(b []byte, num protowire.Number, v float32) []byte {
	if v == 0 {
		return b
	}
	return AppendFixed32Always(b, num, math.Float32bits(v))
}

func AppendFloatAlways(b []byte, num protowire.Number, v float32) []byte {
	return AppendFixed32Always(b, num, math.Float32bits(v))
}

func AppendDouble(b []byte, num protowire.Number, v float64) []byte {
	if v == 0 {
		return b
	}
	return AppendFixed64Always(b, num, math.Float64bits(v))
}

func AppendDoubleAlways(b []byte, num protowire.Number, v float64) []byte {
	return AppendFixed64Always(b, num, math.Float64bits(v))
}

func ReadTag(b *[]byte) (protowire.Number, protowire.Type, error) {
	num, wtyp, n := protowire.ConsumeTag(*b)
	if n < 0 {
		return 0, 0, protowire.ParseError(n)
	}
	*b = (*b)[n:]
	return num, wtyp, nil
}

func Skip(b *[]byte, num protowire.Number, wtyp protowire.Type) error {
	n := protowire.ConsumeFieldValue(num, wtyp, *b)
	if n < 0 {
		return protowire.ParseError(n)
	}
	*b = (*b)[n:]
	return nil
}

func ReadVarint(b *[]byte) (uint64, error) {
	v, n := protowire.ConsumeVarint(*b)
	if n < 0 {
		return 0, protowire.ParseError(n)
	}
	*b = (*b)[n:]
	return v, nil
}

func ReadString(b *[]byte) (string, error) {
	v, n := protowire.ConsumeString(*b)
	if n < 0 {
		return "", protowire.ParseError(n)
	}
	*b = (*b)[n:]
	return v, nil
}

func ReadBytes(b *[]byte) ([]byte, error) {
	v, err := ReadBytesRaw(b)
	if err != nil {
		return nil, err
	}
	return slices.Clone(v), nil
}

func ReadBytesRaw(b *[]byte) ([]byte, error) {
	v, n := protowire.ConsumeBytes(*b)
	if n < 0 {
		return nil, protowire.ParseError(n)
	}
	*b = (*b)[n:]
	return v, nil
}

func ReadFixed32(b *[]byte) (uint32, error) {
	v, n := protowire.ConsumeFixed32(*b)
	if n < 0 {
		return 0, protowire.ParseError(n)
	}
	*b = (*b)[n:]
	return v, nil
}

func ReadFixed64(b *[]byte) (uint64, error) {
	v, n := protowire.ConsumeFixed64(*b)
	if n < 0 {
		return 0, protowire.ParseError(n)
	}
	*b = (*b)[n:]
	return v, nil
}
